INSERT INTO public.categories (code, name_ml, class_min, class_max, age_min, age_max, gender, is_active)
SELECT x.code, x.name_ml, x.class_min, x.class_max, x.age_min, x.age_max, COALESCE(x.gender, 'both'), true
FROM jsonb_to_recordset($clone_seed$[{"code":"SBJ","name_en":"Sub Junior","name_ml":"Sub Junior","age_max":14,"gender":"boys"},{"code":"LP","name_en":"Lower Primary","name_ml":"ലോവർ പ്രൈമറി","class_min":1,"class_max":4,"gender":"both"},{"code":"UP","name_en":"Upper Primary","name_ml":"അപ്പർ പ്രൈമറി","class_min":5,"class_max":7,"gender":"both"},{"code":"HS","name_en":"High School","name_ml":"ഹൈസ്കൂൾ","class_min":8,"class_max":10,"gender":"both"},{"code":"HSS","name_en":"Higher Secondary","name_ml":"ഹയർ സെക്കണ്ടറി","class_min":11,"class_max":12,"gender":"both"},{"code":"JR","name_en":"Junior","name_ml":"Junior","age_min":15,"age_max":20,"gender":"boys"},{"code":"SR","name_en":"Senior","name_ml":"Senior","age_min":21,"age_max":25,"gender":"boys"},{"code":"GN","name_en":"General","name_ml":"ജനറൽ","age_max":25,"gender":"both"},{"code":"CA","name_en":"Campus","name_ml":"കാമ്പസ്","class_min":8,"class_max":10,"notes":"Regular Campus","gender":"both"},{"code":"CG","name_en":"Campus Girls","name_ml":"കാമ്പസ് ഗേൾസ്","gender":"girls"},{"code":"CGP","name_en":"Campus Girls Parallel","name_ml":"കാമ്പസ് ഗേൾസ് പാരലൽ","notes":"Parallel Campus","gender":"girls"}]$clone_seed$::jsonb) AS x(
  code text, name_ml text, class_min integer, class_max integer,
  age_min integer, age_max integer, gender text
)
WHERE NOT EXISTS (
  SELECT 1 FROM public.categories current
  WHERE current.tenant_id IS NULL AND current.code = x.code
);

