unciation","marks":20},{"name":"Presentation Beauty","marks":30},{"name":"Rhythm","marks":20}]},{"event_name":"Qawwali","event_name_ml":"ഖവാലി","total_marks":100,"time_limit":"10m","criteria":[{"name":"Clarity","marks":20},{"name":"Presentation Beauty","marks":30},{"name":"Team Coordination","marks":30},{"name":"Rhythm & Song","marks":20}]},{"event_name":"Daf Mutt","event_name_ml":"ദഫ് മുട്ട്","total_marks":100,"time_limit":"10m","criteria":[{"name":"Baith / Madh","marks":25},{"name":"Rhythm Variation","marks":25},{"name":"Instrument Performance","marks":25},{"name":"Presentation","marks":25}]},{"event_name":"Aravana Mutt","event_name_ml":"അറവന മുട്ട്","total_marks":100,"time_limit":"10m","criteria":[{"name":"Baith","marks":20},{"name":"Pitch","marks":20},{"name":"Expression","marks":20},{"name":"Instrument Skill","marks":20},{"name":"Presentation","marks":20}]},{"event_name":"Poem Recitation / Arabic Poem","event_name_ml":"കവിതാ പാരായണം","total_marks":100,"time_limit":"5m","criteria":[{"name":"Memorization","marks":25},{"name":"Pronunciation","marks":25},{"name":"Expression","marks":25},{"name":"Meaning Clarity","marks":25}]},{"event_name":"Revolutionary Song","event_name_ml":"വിപ്ലവ ഗാനം","total_marks":100,"time_limit":"5m","criteria":[{"name":"Lyrics","marks":25},{"name":"Pitch","marks":25},{"name":"Coordination","marks":20},{"name":"Voice","marks":20},{"name":"Creativity","marks":10}]},{"event_name":"Quiz","event_name_ml":"ക്വിസ്","total_marks":100,"criteria":[{"name":"General Knowledge / Current Affairs / History","marks":50},{"name":"Science / Mental Ability","marks":30},{"name":"Islam / Organizational Topics","marks":20}]},{"event_name":"Language Game","event_name_ml":"ഭാഷാ കളി","total_marks":100,"criteria":[{"name":"Word chain","marks":50},{"name":"Sentence creation","marks":50}]},{"event_name":"DEFAULT_CREATIVE","is_default":true,"total_marks":100,"criteria":[{"name":"Creativity","marks":25},{"name":"Content Quality","marks":25},{"name":"Technical Quality","marks":20},{"name":"Presentation","marks":15},{"name":"Originality","marks":15}]},{"event_name":"DEFAULT_PERFORMANCE","is_default":true,"total_marks":100,"criteria":[{"name":"Presentation","marks":25},{"name":"Skill Quality","marks":25},{"name":"Accuracy","marks":20},{"name":"Creativity","marks":15},{"name":"Confidence","marks":15}]}]$clone_seed$::jsonb)
  LOOP
    SELECT id INTO v_rule_id
    FROM public.scoring_rules
    WHERE tenant_id IS NULL AND event_name = v_rule->>'event_name'
    ORDER BY id LIMIT 1;

    IF v_rule_id IS NULL THEN
      INSERT INTO public.scoring_rules (tenant_id, event_name, event_name_ml, total_marks, time_limit, guidelines, is_default)
      VALUES (NULL, v_rule->>'event_name', v_rule->>'event_name_ml',
        COALESCE((v_rule->>'total_marks')::integer, 100), v_rule->>'time_limit', v_rule->>'guidelines', true)
      RETURNING id INTO v_rule_id;
    END IF;

    FOR v_criterion IN SELECT value FROM jsonb_array_elements(COALESCE(v_rule->'criteria', '[]'::jsonb))
    LOOP
      INSERT INTO public.scoring_criteria (rule_id, name, marks, sort_order)
      SELECT v_rule_id, v_criterion->>'name', (v_criterion->>'marks')::integer,
             COALESCE((v_criterion->>'sort_order')::integer, 0)
      WHERE NOT EXISTS (
        SELECT 1 FROM public.scoring_criteria current
        WHERE current.rule_id = v_rule_id
          AND current.name = v_criterion->>'name'
          AND current.sort_order = COALESCE((v_criterion->>'sort_order')::integer, 0)
      );
    END LOOP;
  END LOOP;
END
$clone_scoring_seed$;

COMMIT;
